# Import the IO module from standard library
import [IO] from "std/io.bpl";

frame main() ret int {
    # Use IO module functions
    IO.print("Hello from IO module!");
    IO.printInt(42);

    # Multiple prints on one line using IO.print (no newline)
    IO.print("The answer is: ");
    IO.print("42");
    IO.print("");  # Just adds newline

    return 0;
}

