    local root: float = sqrt(16.0);
    printf("sqrt(16) = %.1f\n", root);

    return 0;
}

# This would be in a file like 'mymath.bpl'
# ==========================================
# export frame add(a: int, b: int) ret int {
#     return a + b;
# }
