# In your main file:
# import [add, Point] from "./mymath.bpl";

# For now, let's demonstrate with inline code:
extern printf(fmt: string, ...);

# These would be exported in a real module:
frame add(a: int, b: int) ret int {
    return a + b;
}

frame multiply(a: int, b: int) ret int {
    return a * b;
}

struct Calculator {
    lastResult: int,

    frame compute(this: *Calculator, a: int, op: string, b: int) ret int {
        local result: int = 0;
        # Simplified: just add or multiply
        if (op == "+") {
            result = add(a, b);
        } else {
            result = multiply(a, b);
        }
        this.lastResult = result;
        return result;
    }
}

frame main() ret int {
    printf("add(5, 3) = %d\n", add(5, 3));
    printf("multiply(4, 7) = %d\n", multiply(4, 7));

    local calc: Calculator = Calculator { lastResult: 0 };
    printf("calc: 10 + 20 = %d\n", calc.compute(10, "+", 20));
    printf("calc: 6 * 7 = %d\n", calc.compute(6, "*", 7));

    return 0;
}

extern printf(fmt: string, ...);

frame main() ret int {
    # Print different types using printf
    printf("=== IO Module Demo ===\n\n");

    # Strings
    printf("Hello, ");
    printf("World!\n");

    # Integers
    printf("Integer: %d\n", 42);

    # Floats
    printf("Float: %.5f\n", 3.14159);

    # Formatted output
    printf("\nCounting: ");
    loop (local i: int = 1; i <= 5; i = i + 1) {
        printf("%d ", i);
    }
    printf("\n");

    return 0;
}

extern printf(fmt: string, ...);

# Good: Export only what's needed
# export frame publicAPI() { ... }
# frame privateHelper() { ... }  # Not exported

# Example: A well-structured module

# Private helper (not exported)
frame validateInput(input: int) ret bool {
    return input >= 0 && input <= 100;
}

# Private constant
local const MAX_RETRIES: int = 3;

# This would be exported in a real module
struct Config {
    maxItems: int,
    timeout: int,

    frame create() ret Config {
        return Config {
            maxItems: 100,
            timeout: 30
        };
    }

    frame isValid(this: *Config) ret bool {
        return this.maxItems > 0 && this.timeout > 0;
    }
}

# Public function (would be exported)
frame processData(value: int) ret int {
    if (validateInput(value) == false) {
        printf("Invalid input!\n");
        return -1;
    }
    return value * 2;
}

frame main() ret int {
    local config: Config = Config.create();

    printf("Config valid: %d\n", config.isValid());
    printf("Process 50: %d\n", processData(50));
    printf("Process 150: %d\n", processData(150));

    return 0;
}

