import [IO] from "std/io.bpl";

# Math module functions
frame abs(n: int) ret int {
    if (n < 0) {
        return -n;
    }
    return n;
}

frame max(a: int, b: int) ret int {
    if (a > b) { return a; }
    return b;
}

frame min(a: int, b: int) ret int {
    if (a < b) { return a; }
    return b;
}

frame clamp(val: int, lo: int, hi: int) ret int {
    if (val < lo) { return lo; }
    if (val > hi) { return hi; }
    return val;
}

frame main() ret int {
    IO.print("abs(-5) = ");
    IO.printInt(abs(-5));
    IO.print("\n");

    IO.print("max(10, 20) = ");
    IO.printInt(max(10, 20));
    IO.print("\n");

    IO.print("min(10, 20) = ");
    IO.printInt(min(10, 20));
    IO.print("\n");

    IO.print("clamp(50, 0, 100) = ");
    IO.printInt(clamp(50, 0, 100));
    IO.print("\n");

    IO.print("clamp(-10, 0, 100) = ");
    IO.printInt(clamp(-10, 0, 100));
    IO.print("\n");

    return 0;
}
